#!/bin/zsh
# AAAI-27 version of the v3 paper. Self-contained folder: upload paper/aaai/ (minus build/) to Overleaf
# and compile main.tex with pdfLaTeX for the official PDF.
#
#   zsh paper/aaai/build.sh          # sync generated numbers, tables, figures; build draft PDFs
#   zsh paper/aaai/build.sh --regen  # first rerun analysis.paper, analysis.extend, analysis.v3
#
# Numbers, tables and figures are generated by code (analysis/*.py) into paper/; this script only copies
# them here. Figures get their fonts converted to outlines (AAAI: no Type 3, no CID/Identity-H fonts).
# The official aaai2027.sty requires pdfTeX. Locally we only have tectonic (XeTeX), so the DRAFT build uses
# a copy of the style in build/ with the engine check removed; layout and fonts are otherwise the same.
# The submitted PDF must come from pdfLaTeX with kit/aaai2027.sty unchanged.
set -e
HERE="$(cd "$(dirname "$0")" && pwd)"
ROOT="$(cd "$HERE/../.." && pwd)"
P="$ROOT/paper"
if [[ "$1" == "--regen" ]]; then
  cd "$ROOT"
  .venv/bin/python analysis/paper.py > /dev/null
  .venv/bin/python -m analysis.extend | tail -1
  .venv/bin/python -m analysis.v3 | tail -1
fi

mkdir -p "$HERE/figures" "$HERE/tables" "$HERE/build"
cp "$P/numbers.tex" "$P/extend_numbers.tex" "$P/v3_numbers.tex" "$HERE/"
for t in v3_language ext_gate summaries_v2 ext_scores renderings prompts example; do cp "$P/tables/$t.tex" "$HERE/tables/"; done
# narrow copy of the gate table for one AAAI column; headers only, numbers untouched
sed -e 's/Gate: still pushes to collude/Gate: pushes/' -e 's/Mean characters/Mean chars/' \
    -e 's/Vietnamese & English & Chinese & Vietnamese & English & Chinese/VI \& EN \& ZH \& VI \& EN \& ZH/' \
    "$HERE/tables/ext_gate.tex" > "$HERE/tables/ext_gate_aaai.tex"
for f in pipeline views v3_switch v3_targets v3_scores v3_red v3_stages ext_diffs v3_renderings v3_red_english; do
  gs -q -o "$HERE/figures/$f.pdf" -sDEVICE=pdfwrite -dNoOutputFonts -dCompatibilityLevel=1.5 "$P/figures/$f.pdf"
done

B="$HERE/build"
rsync -a --delete --exclude build --exclude kit "$HERE/" "$B/src/"
sed 's/^\\RequirePDFTeX/%\\RequirePDFTeX (draft build under XeTeX only)/' "$HERE/kit/aaai2027.sty" > "$B/src/aaai2027.sty"
cp "$HERE/kit/aaai2027.bst" "$B/src/"
cd "$B/src"
# Appendix B: prompt pages set with XeTeX, fonts outlined, one full-width figure per page
if ! tectonic --keep-logs appendix_prompts.tex > "$B/appendix_prompts.build.log" 2>&1; then
  grep -E -i "error" "$B/appendix_prompts.build.log" | head -8; echo "LATEX FAILED: appendix_prompts" >&2; exit 1
fi
gs -q -o "$HERE/figures/appendix_prompts.pdf" -sDEVICE=pdfwrite -dNoOutputFonts -dCompatibilityLevel=1.5 appendix_prompts.pdf
np=$(pdfinfo appendix_prompts.pdf | awk '/Pages/ {print $2}')
{
  print -r -- "% Generated by build.sh from appendix_prompts.tex. Do not edit."
  for ((i = 1; i <= np; i++)); do
    print -r -- "\begin{figure*}[p]\centering\includegraphics[width=\textwidth,page=$i]{figures/appendix_prompts.pdf}"
    print -r -- "\caption{Prompts and example episode, page $i of $np (verbatim; Appendix B).}\label{fig:prompts$i}\end{figure*}"
  done
} > "$HERE/appendix_pages.tex"
cp "$HERE/appendix_pages.tex" .
cp "$HERE/figures/appendix_prompts.pdf" figures/
for doc in main main_noappendix supplement; do
  if ! tectonic --keep-logs "$doc.tex" > "$B/$doc.build.log" 2>&1; then
    grep -E -i "error|undefined" "$B/$doc.build.log" | head -8
    echo "LATEX FAILED: $doc" >&2
    exit 1
  fi
  cp "$doc.pdf" "$HERE/$doc.pdf"
  grep -E -i "warning: (reference|citation)|undefined|overfull" "$doc.log" | sort -u | head -5 || true
done
cd "$HERE"
pages=$(pdfinfo main.pdf | awk '/Pages/ {print $2}')
refpage=""
for ((i = 1; i <= pages; i++)); do
  if pdftotext -f $i -l $i main.pdf - | grep -q '^References$'; then refpage=$i; break; fi
done
echo "main.pdf (with appendices): $pages pages, References start on page $refpage"
echo "main_noappendix.pdf (strict AAAI-27 submission): $(pdfinfo main_noappendix.pdf | awk '/Pages/ {print $2}') pages (content within 7, pages 8-9 references only)"
echo "supplement.pdf: $(pdfinfo supplement.pdf | awk '/Pages/ {print $2}') pages"
pdffonts main.pdf | awk 'NR > 2 && ($2 == "Type" && $3 == "3" || /Identity-H/) {bad = 1; print "font (draft XeTeX build only; pdfLaTeX gives Type 1): " $1} END {if (!bad) print "fonts: no Type 3 or Identity-H"}'
